// Filtrar solo keywords con intención transaccional de alquiler
const rows = $('GSC · Fetch Queries 5 Categorías').first().json.rows || [];
const previousRows = $('GSC · Semana Anterior (Comparar)').first().json.rows || [];

// Palabras clave que indican intención de alquiler/transacción
const transaccionalPatterns = [
  'alquil', 'rent', 'arrendam', 'precio', 'tarifa', 'coste',
  'contratar', 'presupuesto', 'cuanto cuesta', 'donde alquilar',
  'mejor', 'comparar', 'barato', 'económico', 'oferta',
  'cerca de', 'en madrid', 'en barcelona', 'en sevilla',
  'por días', 'por semana', 'por mes', 'mensual', 'diario',
  'con operador', 'sin operador'
];

const filtered = rows.filter(row => {
  const query = (row.keys?.[0] || '').toLowerCase();
  return transaccionalPatterns.some(p => query.includes(p));
}).map(row => {
  const query = row.keys?.[0] || '';
  const page = row.keys?.[1] || '';

  // Buscar datos de la semana anterior para esta query
  const prev = previousRows.find(p => 
    (p.keys?.[0] || '') === query && (p.keys?.[1] || '') === page
  );

  const posActual = row.position || 0;
  const posAnterior = prev ? (prev.position || 0) : null;
  const cambio = posAnterior !== null ? posAnterior - posActual : null;

  return {
    query,
    page,
    clicks: row.clicks || 0,
    impressions: row.impressions || 0,
    ctr: ((row.ctr || 0) * 100).toFixed(2) + '%',
    posicion_actual: posActual.toFixed(1),
    posicion_anterior: posAnterior ? posAnterior.toFixed(1) : 'N/A',
    cambio_posicion: cambio !== null ? cambio.toFixed(1) : 'Nueva',
    tendencia: cambio === null ? '🆕' : cambio > 0 ? '📈' : cambio < 0 ? '📉' : '➡️'
  };
});

// Ordenar por impresiones (mayor potencial)
filtered.sort((a, b) => b.impressions - a.impressions);

return [{ json: { 
  total_queries: filtered.length,
  keywords: filtered,
  fecha_analisis: $now.toFormat('dd/MM/yyyy')
} }];

const data = $input.first().json;
const keywords = data.keywords || [];

// Keywords que han caído 3+ posiciones
const caidas = keywords.filter(kw => {
  const cambio = parseFloat(kw.cambio_posicion);
  return !isNaN(cambio) && cambio < -2;
}).sort((a, b) => parseFloat(a.cambio_posicion) - parseFloat(b.cambio_posicion));

// Keywords con oportunidad (posición 5-20 con impresiones altas)
const oportunidades = keywords.filter(kw => {
  const pos = parseFloat(kw.posicion_actual);
  return pos >= 5 && pos <= 20 && kw.impressions >= 50;
}).sort((a, b) => b.impressions - a.impressions);

// Detectar canibalización: misma query en múltiples páginas
const queryPages = {};
keywords.forEach(kw => {
  if (!queryPages[kw.query]) queryPages[kw.query] = [];
  queryPages[kw.query].push({ page: kw.page, posicion: kw.posicion_actual });
});

const canibalizaciones = Object.entries(queryPages)
  .filter(([_, pages]) => pages.length > 1)
  .map(([query, pages]) => ({ query, paginas_compitiendo: pages }));

return [{ json: {
  ...data,
  caidas,
  total_caidas: caidas.length,
  oportunidades,
  total_oportunidades: oportunidades.length,
  canibalizaciones,
  total_canibalizaciones: canibalizaciones.length
} }];

