const data = $('Parsear Contenido SEO').item.json;
const canibalizaciones = data.canibalizaciones || [];

let alertaTexto = '';
if (canibalizaciones.length > 0) {
  alertaTexto = '⚠️ **ALERTA DE CANIBALIZACIÓN**\n\n';
  canibalizaciones.forEach((c, i) => {
    alertaTexto += `**${i + 1}. "${c.query}"** → ${c.paginas_compitiendo.length} páginas compitiendo:\n`;
    c.paginas_compitiendo.forEach(p => {
      alertaTexto += `   - ${p.page} (pos: ${p.posicion})\n`;
    });
    alertaTexto += '\n';
  });
  alertaTexto += '🎯 **Acción recomendada:** Consolidar contenido, implementar canonical tags o redirigir la página más débil.';
} else {
  alertaTexto = '✅ No se detectaron canibalizaciones esta semana.';
}

return [{ json: {
  ...data,
  alerta_canibalizacion: alertaTexto,
  hay_canibalizacion: canibalizaciones.length > 0
} }];

